use realm_agent::{model::*,policy_runtime::PolicyRuntime};
use std::{collections::BTreeSet,path::{Path,PathBuf},sync::atomic::{AtomicU64,Ordering}};
fn entity(guid:u64,class:u8,x:f32)->Entity{Entity{guid,kind:Kind::Player,entry:0,name:None,position:Some(Position{map:1,x,..Default::default()}),health:Some(100),max_health:Some(100),mana:Some(100),max_mana:Some(100),rage:None,level:Some(60),class:Some(class),form:Some(0),flags:0,duel_arbiter:0,auras:BTreeSet::new(),target:None,updated_ms:0}}
fn world(class:u8)->WorldView{let mut w=WorldView{class:8,self_guid:1,position:Some(Position{map:1,..Default::default()}),now_ms:100,sequence:1,..Default::default()};w.objects.insert(1,entity(1,8,0.));w.objects.insert(2,entity(2,class,20.));w.spells.insert(10181);w}
fn bundle()->PathBuf{Path::new(env!("CARGO_MANIFEST_DIR")).join("config/policies")}
#[test]fn every_class_uses_its_own_real_file(){for(class,file)in [(1,"50-mage-vs-warrior"),(4,"51-mage-vs-rogue"),(9,"52-mage-vs-warlock"),(5,"53-mage-vs-priest"),(3,"54-mage-vs-hunter"),(7,"55-mage-vs-shaman"),(11,"56-mage-vs-druid"),(2,"57-mage-vs-paladin"),(8,"58-mage-vs-mage")]{let w=world(class);let mut r=PolicyRuntime::new(Some(bundle())).unwrap();let a=r.choose(&w,2).unwrap();assert!(matches!(a[0],Action::Cast{spell:10181,..}),"{}",r.status());assert!(r.status().contains(file),"{}",r.status());}}
#[test]fn specific_interrupt_outscores_earlier_common_barrier(){let mut w=world(9);w.spells.extend([2139,13033]);w.casts.insert(2,CastView{spell:6215,ends_ms:1000});let mut r=PolicyRuntime::new(Some(bundle())).unwrap();let a=r.choose(&w,2).unwrap();assert!(matches!(a[0],Action::Cast{spell:2139,..}),"{}",r.status());assert!(r.status().contains("52-mage-vs-warlock"));}
#[test]fn druid_form_is_observed_and_changes_the_decision(){let mut w=world(11);w.spells.insert(12826);w.objects.get_mut(&1).unwrap().health=Some(35);let mut r=PolicyRuntime::new(Some(bundle())).unwrap();assert!(matches!(r.choose(&w,2).unwrap()[0],Action::Cast{spell:12826,..}),"{}",r.status());w.objects.get_mut(&2).unwrap().form=Some(1);let a=r.choose(&w,2).unwrap();assert!(!matches!(a[0],Action::Cast{spell:12826,..}));}
#[test]fn known_immunity_waits_and_unknown_class_does_not_become_known(){let mut w=world(2);w.objects.get_mut(&2).unwrap().auras.insert(1020);let mut r=PolicyRuntime::new(Some(bundle())).unwrap();assert!(r.choose(&w,2).unwrap().is_empty(),"{}",r.status());w.objects.get_mut(&2).unwrap().class=None;assert!(r.choose(&w,2).is_none());}
#[test]fn hot_bundle_is_pinned_then_changes_after_combat(){static NEXT:AtomicU64=AtomicU64::new(0);let dir=std::env::temp_dir().join(format!("mage-bundle-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir(&dir).unwrap();let path=dir.join("50-mage-vs-warrior.json");std::fs::copy(bundle().join("50-mage-vs-warrior.json"),&path).unwrap();let mut w=world(1);w.objects.get_mut(&1).unwrap().flags=0x80000;let mut r=PolicyRuntime::new(Some(dir.clone())).unwrap();assert!(r.choose(&w,2).is_some());let mut doc:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();doc["enabled"]=false.into();doc["revision"]=900.into();std::fs::write(&path,doc.to_string()).unwrap();w.now_ms=1200;assert!(r.choose(&w,2).is_some());r.combat_ended();w.objects.get_mut(&1).unwrap().flags=0;assert!(r.choose(&w,2).is_none());std::fs::remove_dir_all(dir).unwrap();}
#[test]fn observed_counterspell_changes_mirror_without_inventing_enemy_cd(){let mut w=world(8);w.objects.get_mut(&2).unwrap().position=Some(Position{map:1,x:15.,..Default::default()});w.spells.insert(10199);let mut r=PolicyRuntime::new(Some(bundle())).unwrap();r.choose(&w,2);assert!(!r.status().contains("after-observed-counterspell"));w.observed_spells.entry(2).or_default().insert(2139,w.now_ms);let a=r.choose(&w,2).unwrap();assert!(matches!(a[0],Action::Cast{spell:10199,..}),"{}",r.status());assert!(r.status().contains("after-observed-counterspell"));w.now_ms+=5001;r.choose(&w,2);assert!(!r.status().contains("after-observed-counterspell"));}
#[test]fn urgent_interrupt_cancels_own_damage_cast_then_sends_counter(){let mut w=world(9);w.spells.insert(2139);w.pending_spell=Some(10181);w.casting_until=5000;w.gcd_until=2000;w.casts.insert(2,CastView{spell:6215,ends_ms:4000});let mut r=PolicyRuntime::new(Some(bundle())).unwrap();let a=r.choose(&w,2).unwrap();assert!(matches!(a[0],Action::CancelCast(10181)));assert!(matches!(a[1],Action::Cast{spell:2139,..}));}

#[test]fn observed_sheep_is_not_immediately_broken_by_own_damage(){let mut w=world(11);w.spells.insert(12826);w.objects.get_mut(&2).unwrap().auras.insert(12826);let mut r=PolicyRuntime::new(Some(bundle())).unwrap();assert!(r.choose(&w,2).unwrap().is_empty(),"{}",r.status());assert!(r.status().contains("hold-observed-polymorph"));}
